def _title(m):
    mm = re.match(r"^【(.+?)】", m)
    return mm.group(1) if mm else ""

segs = []
for i, s in enumerate(src["translations"]):
    segs.append({"section": _title(MODS[i]), "original_preview": s["original_preview"], "modern": MODS[i]})

out = {
    "id": src["id"], "title": src["title"], "translator": src.get("translator", ""),
    "mode": "baihua", "intro": INTRO, "sutraPath": f"../sutras/{TID}.json", "translations": segs,
}
json.dump(out, open(f"data/modern-translation/{TID}.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(TID, "ok", len(segs), "段")
